INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N097-01','CN0225','S097-01','历史实际工艺','p1–5、13–18','2015年监测报告明确清洗水沉淀压滤优先回用、必要时RO，含重金属浓水外委；无害化还原液RO浓液含草酸氧钒回用或销售。旧同行环评三效蒸发不移入2015流程。截图受阻，图3-5文字箭头不清，未取数值。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N097-02','CN0225','S097-01','水质测点与生产负荷','表6-1、6-4、6-6','2015-06-08/09实际处理38/42t/d，负荷76/84%；水质测点雨水口周边地下水，非生产废水，监测无降雨。原水和RO出水未测。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N097-03','CN0225','S097-01','投资与容量','p4–5','实际800万元，环保240万（废水118、噪声20、废气55、固废45、绿化等2）；事故池255、初雨215、消防198m³，非流量；历史厂址清城区龙塘镇井岭村S253南侧。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N097-04','CN0368','S097-02','正式批复与废水','附件8 p1–4截图','新环审发〔2025〕8号，83#厂房，五产品500/500/200/500/100t/a；项目3000万环保147万。分质蒸馏、中和、活性炭、絮凝沉淀及纳管；初雨回尾气吸收、蒸汽冷凝回循环；危废暂存实时不超过3t；纯水RO元件不是废水膜。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N097-05','CN0368','S097-03','试生产','正文','2025-10-24报道试生产；S097-04另列环保设施10-25竣工、10-28拟调试，口径不同，不作为验收。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N097-06','CN0368','S097-04','调试公示','正文','2025-10-25环保设施竣工，拟10-28调试，未见验收报告。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N097-07','CN0369','S097-05','建设规模及计划','资格预审p1截图','新经审备〔2025〕7号，约15亩，一期1000t/a铁系，二期预留1000t/a铜镍系；5807万元估算，计划2025-10-25至2027-02-23，实际开工令未知。固光项目验收非催化剂验收。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N097-08','CN0370','S097-06','监管名单身份','第53项','信用代码91627100MABUQ82X0R，大气/土壤监管；S097-07第107项列名，不证明产能或在产。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N097-09','CN0368','S097-06','监管及披露名单','第52项','信用代码91627100MACQWWEP8E，S097-07第136项；未取年度披露。','WEB_PRIMARY','WEB_TEXT','2026-11-28');
